css:
.warpcast-button {
  position: relative;
  width: 130px;
  height: 35px;
  border-radius: 30px;
  background-color: rgb(41, 30, 46);
  color: aliceblue;
  border: 1px #291041 solid;
  overflow: hidden;
  cursor: pointer;
}

.text1 {
  font-size: 15px;
  font-weight: 600;
  margin-left: 22%;
}

.text2 {
  position: absolute;
  top: 27%;
  left: -90px;
  font-weight: 700;
  font-size: 12px;
  color: white;
}

.icon {
  position: absolute;
  top: -2px;
  left: 0;
  transition: transform 0.5s;
  border-radius: 50%;
}

.icon::before {
  position: absolute;
  left: -100px;
  top: 0;
  z-index: -1;
  content: "";
  width: 120px;
  height: 36px;
  border-radius: 30px;
  background-color: #2c0772;
}

.warpcast-button:hover .icon {
  transform: translateX(92px);
  transition: transform 0.5s;
}

.warpcast-button:hover .text2 {
  transform: translateX(100px);
  transition: transform 0.6s;
}

.warpcast-button:active {
  transform: scale(1.03);
}
